/* ============================================================
   PATCH v1.4.5 — приказы/ссылки в logModal
   ============================================================ */

/* 1. Скрываем дублирующий <label> внутри <details class="log-section">
      (у приказов и ссылок label идёт из статического HTML, а summary
      создаёт PATCH 1.0.4 — из-за этого заголовок дублируется). */
#logModal details.log-section > .log-section-body > .form-group > label {
    display: none !important;
}
/* 2. «Схлопываем» обёртку .form-group — дети рендерятся напрямую
      в .log-section-body, без лишнего flex-контейнера. */
#logModal details.log-section > .log-section-body > .form-group {
    display: contents !important;
}
/* 3. Premium-стили <details class="log-section"> — как #taskModal details.task-section */
#logModal details.log-section {
    background: var(--trk-hover-row) !important;
    border: 1px solid var(--trk-card-border) !important;
    border-radius: 12px !important;
    margin-bottom: 12px !important;
    overflow: hidden !important;
}
#logModal details.log-section > summary {
    cursor: pointer !important;
    padding: 12px 16px !important;
    font-size: 0.85rem !important;
    font-weight: 700 !important;
    color: var(--trk-text) !important;
    list-style: none !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    user-select: none !important;
    transition: background 0.15s !important;
}
#logModal details.log-section > summary:hover {
    background: rgba(245,215,110,0.06) !important;
}
#logModal details.log-section > summary::-webkit-details-marker { display: none !important; }
#logModal details.log-section > summary::before {
    content: '▶' !important;
    font-size: 0.65em !important;
    color: var(--trk-meta) !important;
    transition: transform 0.2s ease !important;
    display: inline-block !important;
}
#logModal details.log-section[open] > summary::before {
    transform: rotate(90deg) !important;
}
#logModal details.log-section > summary .cnt {
    margin-left: auto !important;
    font-size: 0.7rem !important;
    padding: 2px 8px !important;
    border-radius: 8px !important;
    background: var(--trk-filter-active-bg) !important;
    color: var(--trk-filter-active) !important;
    font-weight: 800 !important;
    min-width: 20px !important;
    text-align: center !important;
}
#logModal details.log-section > summary .cnt:empty { display: none !important; }
#logModal details.log-section > .log-section-body {
    padding: 4px 16px 16px !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 8px !important;
}
/* 4. Внутри <details> кнопки и подсказки — компактнее */
#logModal details.log-section .log-add-btn {
    align-self: flex-start !important;
    padding: 6px 14px !important;
    font-size: 0.82rem !important;
}
#logModal details.log-section .task-links-list {
    display: flex !important;
    flex-direction: column !important;
    gap: 6px !important;
}
/* 5. «— нет —» внутри details выглядит как empty-hint */
#logModal details.log-section .task-links-empty {
    font-size: 0.82rem !important;
    color: var(--trk-meta) !important;
    font-style: italic !important;
    padding: 6px 2px !important;
}
/* 6. Светлая тема */
body.trk-theme-light #logModal details.log-section {
    background: #f7f9fa !important;
    border-color: rgba(0,0,0,0.12) !important;
}
body.trk-theme-light #logModal details.log-section > summary:hover {
    background: rgba(0,137,123,0.06) !important;
}

/* ============================================================
   PATCH v1.4.5 — бейдж прогресса гипотез на плитке задачи.
   Добавляем через MutationObserver, а не через замену taskCardRowGrid:
   так неважно, был ли применён v1.4.4 или откачен, и какие ещё патчи
   трогали карточку задачи.
   ============================================================ */
(function(){
    'use strict';
    if (window.__trkHypBadgeV145) return;
    window.__trkHypBadgeV145 = true;

    function _computeBadge(t) {
        if (!t || !Array.isArray(t.hypotheses) || !t.hypotheses.length) return null;
        var hyps = t.hypotheses.filter(function(x){ return x && x.kind === 'hypothesis'; });
        var tasks = t.hypotheses.filter(function(x){ return x && x.kind === 'task'; });
        if (!hyps.length && !tasks.length) return null;
        var hd = hyps.filter(function(x){ return x.status === 'done'; }).length;
        var td = tasks.filter(function(x){ return x.status === 'done'; }).length;
        var parts = [];
        if (hyps.length) parts.push('🧪 ' + hd + '/' + hyps.length);
        if (tasks.length) parts.push('📌 ' + td + '/' + tasks.length);
        var allDone = (hd === hyps.length && td === tasks.length);
        var anyDone = (hd > 0 || td > 0);
        var cls = allDone ? 'hyp-badge-done' : (anyDone ? 'hyp-badge-progress' : 'hyp-badge-new');
        return {
            text: parts.join(' · '),
            cls: cls,
            title: 'Гипотезы: ' + hd + '/' + hyps.length + ' · Задания: ' + td + '/' + tasks.length
        };
    }

    function _apply() {
        var list = document.getElementById('tasksFullList');
        if (!list) return;
        var st = window.__trkState || {};
        var byId = {};
        (st.tasks || []).forEach(function(t){ if (t && t.id) byId[t.id] = t; });
        list.querySelectorAll('.task-card, .dict-item').forEach(function(card){
            var id = card.getAttribute('data-id');
            if (!id) return;
            var info = _computeBadge(byId[id]);
            var existing = card.querySelector('.task-card-badge.hyp-badge');
            if (!info) {
                if (existing) existing.remove();
                return;
            }
            var badge = existing;
            if (!badge) {
                badge = document.createElement('span');
                badge.className = 'task-card-badge hyp-badge ' + info.cls;
                var target = card.querySelector('.task-card-topright')
                          || card.querySelector('.dict-actions')
                          || card.querySelector('.task-card-head');
                if (target) target.appendChild(badge);
                else card.appendChild(badge);
            }
            badge.className = 'task-card-badge hyp-badge ' + info.cls;
            badge.textContent = info.text;
            badge.title = info.title;
        });
    }

    function _observe() {
        var list = document.getElementById('tasksFullList');
        if (!list || list._hypBadgeObsV145) return;
        list._hypBadgeObsV145 = true;
        new MutationObserver(function(){ setTimeout(_apply, 30); }).observe(list, { childList: true });
        setTimeout(_apply, 60);
    }

    function boot() {
        _observe();
        setTimeout(function(){ _observe(); _apply(); }, 300);
        setTimeout(_apply, 1000);
        setTimeout(_apply, 2500);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot);
    } else {
        boot();
    }

    document.addEventListener('click', function(e){
        if (!e.target || !e.target.closest) return;
        if (e.target.closest('.tracker-tab[data-tab="tasks"]') ||
            e.target.closest('#tskViewSeg button') ||
            e.target.closest('#tskViewMode button')) {
            setTimeout(_apply, 200);
            setTimeout(_apply, 500);
        }
    }, true);

    window.__trkAddHypBadges = _apply;
})();
